INSERT INTO `advantages` VALUES (1,2,1,'The MCG Guarantee','{\"time\":1635972201501,\"blocks\":[{\"id\":\"NR1HieJTg_\",\"type\":\"paragraph\",\"data\":{\"text\":\"High-quality work that you can be proud of. Guaranteed.\"}}],\"version\":\"2.22.2\"}','2021-06-10 18:10:59','2021-11-03 20:43:21',NULL),(2,2,2,'Personalized Design','{\"time\":1635972108519,\"blocks\":[{\"id\":\"2x3XSygk3t\",\"type\":\"paragraph\",\"data\":{\"text\":\"All materials are handpicked by our talented design team\"}}],\"version\":\"2.22.2\"}','2021-06-10 18:12:06','2021-11-03 20:41:48',NULL),(3,2,3,'Project Management','{\"time\":1629989242475,\"blocks\":[{\"id\":\"3FtfOm5nl-\",\"type\":\"paragraph\",\"data\":{\"text\":\"The foundation of every successful renovation is the project management.&nbsp;\"}}],\"version\":\"2.22.0\"}','2021-06-10 18:13:13','2021-08-26 14:47:22',NULL),(4,1,1,'Finish Materials','{\"time\":1635972126227,\"blocks\":[{\"id\":\"OfEcol_RTb\",\"type\":\"paragraph\",\"data\":{\"text\":\"Based on your preferences, our creative design team will handpick all decor materials with multiple options for you to choose from\"}}],\"version\":\"2.22.2\"}','2021-06-10 18:13:37','2021-11-03 20:42:06',NULL),(5,1,2,'Keep Track','{\"time\":1632424697284,\"blocks\":[{\"id\":\"f1Mw5TNm09\",\"type\":\"paragraph\",\"data\":{\"text\":\"You will have access to the live completion status of your project, with the start/end dates, completion percentage and much more. The report is updated on daily basis, based on our performance\"}}],\"version\":\"2.22.2\"}','2021-06-10 18:14:20','2021-09-23 19:18:17',NULL),(6,1,3,'Project Management','{\"time\":1629989397219,\"blocks\":[{\"id\":\"u68e5010yy\",\"type\":\"paragraph\",\"data\":{\"text\":\"\\t The foundation of every successful renovation is the project management. \"}}],\"version\":\"2.22.0\"}','2021-06-10 18:14:39','2021-08-26 14:49:57',NULL),(7,1,1,'Test','{\"time\":1623349775107,\"blocks\":[{\"type\":\"paragraph\",\"data\":{\"text\":\"test\"}}],\"version\":\"2.20.0\"}','2021-06-10 18:29:35','2021-06-10 18:29:38','2021-06-10 18:29:38'),(8,1,5,'TEST11','{\"time\":1630565308298,\"blocks\":[{\"id\":\"OMFDPu9wMy\",\"type\":\"paragraph\",\"data\":{\"text\":\"TESTING11\"}}],\"version\":\"2.22.0\"}','2021-09-02 06:48:16','2021-09-02 06:48:36','2021-09-02 06:48:36'),(9,1,1,'Know the cost of your project before you start','{\"time\":1634340340162,\"blocks\":[],\"version\":\"2.22.2\"}','2021-10-15 23:25:40','2021-10-15 23:31:21','2021-10-15 23:31:21'),(10,3,1,'Transparent Pricing','{\"time\":1660413939437,\"blocks\":[{\"id\":\"xa_qZ9LYEY\",\"type\":\"paragraph\",\"data\":{\"text\":\"No surprises, ever. The final project proposal is itemized and includes everything. We won’t nickel and dime you at any point – that’s a promise.\"}}],\"version\":\"2.23.2\"}','2022-07-12 10:59:43','2022-08-13 18:05:40',NULL),(11,3,2,'Customer Delight','{\"time\":1658929335318,\"blocks\":[{\"id\":\"BYBlCZyUYp\",\"type\":\"paragraph\",\"data\":{\"text\":\"Our goal is to deliver best-in-class customer service and make home renovations a memorable experience for our customers–in a good way!\"}}],\"version\":\"2.23.2\"}','2022-07-12 11:00:45','2022-07-27 13:42:17',NULL),(12,3,3,'Convenience','{\"time\":1660424404952,\"blocks\":[{\"id\":\"4EanYVaTc_\",\"type\":\"paragraph\",\"data\":{\"text\":\"Your renovation team manages every single task from start to finish. Once you <a href=\\\"https://moderncitigroup.com/ready-solutions\\\" target=\\\"_blank\\\">choose a design</a>, the work begins promptly.\"}}],\"version\":\"2.23.2\"}','2022-07-12 11:00:58','2022-08-13 21:00:05',NULL),(13,3,4,'Quality','{\"time\":1660413949042,\"blocks\":[{\"id\":\"9yQTiHg7W0\",\"type\":\"paragraph\",\"data\":{\"text\":\"We are selective about our materials and partners. We treat your project with the utmost care and deliver nothing short of perfection.\"}}],\"version\":\"2.23.2\"}','2022-07-12 11:01:35','2022-08-13 18:05:49',NULL);
