--
-- Table structure for table `callcenter_calls`
--

DROP TABLE IF EXISTS `callcenter_calls`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `callcenter_calls` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `from_uid` bigint(20) unsigned DEFAULT NULL,
  `lead_id` bigint(20) unsigned DEFAULT NULL,
  `phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_denied` tinyint(1) DEFAULT NULL,
  `is_busy` tinyint(1) DEFAULT NULL,
  `is_missing` tinyint(1) DEFAULT NULL,
  `started_at` timestamp NULL DEFAULT current_timestamp(),
  `finished_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `callcenter_calls_from_uid_foreign` (`from_uid`),
  KEY `callcenter_calls_lead_id_foreign` (`lead_id`),
  CONSTRAINT `callcenter_calls_from_uid_foreign` FOREIGN KEY (`from_uid`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `callcenter_calls_lead_id_foreign` FOREIGN KEY (`lead_id`) REFERENCES `leads` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

