  CONSTRAINT `request_room_has_works_double_replace_id_foreign` FOREIGN KEY (`double_replace_id`) REFERENCES `request_work_replaces` (`id`) ON DELETE CASCADE,
  CONSTRAINT `request_room_has_works_room_id_foreign` FOREIGN KEY (`room_id`) REFERENCES `request_has_rooms` (`id`) ON DELETE CASCADE,
