INSERT INTO `slides` VALUES (3,NULL,4,1,NULL,'Kitchen Remodeling',NULL,NULL,NULL,'{\"time\":1650884378221,\"blocks\":[{\"id\":\"fv7QDEAk8i\",\"type\":\"paragraph\",\"data\":{\"text\":\"Helping you create the kitchen you\'ve always wanted.\"}}],\"version\":\"2.23.2\"}','2021-06-08 08:40:44','2022-04-25 10:59:38',NULL,0),(4,NULL,4,4,NULL,'Commercial Remodeling',NULL,NULL,NULL,'{\"time\":1658365816694,\"blocks\":[{\"id\":\"5iSTZyeMn3\",\"type\":\"paragraph\",\"data\":{\"text\":\"We will help you become memorable in the eyes of your clients and employees.\"}}],\"version\":\"2.23.2\"}','2021-06-08 08:43:51','2022-07-21 01:10:21',NULL,0),(5,NULL,4,3,NULL,'Bathroom Renovation',NULL,NULL,NULL,'{\"time\":1644380721300,\"blocks\":[{\"id\":\"IgIMwwx5rY\",\"type\":\"paragraph\",\"data\":{\"text\":\"Don\'t just remodel it, Transform it!\"}}],\"version\":\"2.22.2\"}','2021-06-08 08:44:55','2022-02-09 04:25:21',NULL,0),(6,NULL,4,4,NULL,'Residential Remodeling',NULL,NULL,NULL,'{\"time\":1644380768316,\"blocks\":[{\"id\":\"M8dNeSrEqS\",\"type\":\"paragraph\",\"data\":{\"text\":\"Renovate your entire apartment/house.&nbsp;\"}}],\"version\":\"2.22.2\"}','2021-06-08 08:46:17','2022-02-09 04:26:08',NULL,0),(7,NULL,7,1,NULL,'Get Your Estimate',NULL,NULL,NULL,'{\"time\":1647726354856,\"blocks\":[{\"id\":\"DV9t176jIC\",\"type\":\"paragraph\",\"data\":{\"text\":\"Create your project in minutes using our online builder, and get a free estimate for it\"}}],\"version\":\"2.23.2\"}','2021-06-08 09:26:05','2022-03-19 21:45:55',NULL,0),(8,NULL,7,2,NULL,'Detailed proposal',NULL,NULL,NULL,'{\"time\":1644380782017,\"blocks\":[{\"id\":\"uxWYpmLP6p\",\"type\":\"paragraph\",\"data\":{\"text\":\"Get a clear, detailed completion list with a detailed breakdown and everything included in it. We make sure to include any issues known to frequently occur, so nothing comes as a surprise to you down the road.\"}}],\"version\":\"2.22.2\"}','2021-06-08 09:28:07','2022-02-09 04:26:22',NULL,0),(9,NULL,7,3,NULL,'Design & Materials',NULL,NULL,NULL,'{\"time\":1641271967395,\"blocks\":[{\"id\":\"D8bNzDVrxX\",\"type\":\"paragraph\",\"data\":{\"text\":\"World-level design experts that work at MCG select the most reliable, high-quality materials based on your personal preference and budget. Every detail is considered, from the lighting temperature to the paint color.\"}}],\"version\":\"2.22.2\"}','2021-06-08 09:30:39','2022-01-04 04:52:47',NULL,0),(10,NULL,7,4,NULL,'Renovation & remodeling',NULL,NULL,NULL,'{\"time\":1644379856771,\"blocks\":[{\"id\":\"TmuhrL7tn0\",\"type\":\"paragraph\",\"data\":{\"text\":\"Watch the transformation begin. With the access to the project completion report you will always know what is accomplished each day,&nbsp; giving you the power to track the progress in real-time.&nbsp;\"}}],\"version\":\"2.22.2\"}','2021-06-08 09:32:35','2022-02-09 04:10:57',NULL,0),(11,NULL,7,5,NULL,'Final Walkthrough',NULL,NULL,NULL,'{\"time\":1644380992604,\"blocks\":[{\"id\":\"jUGQJl-0TF\",\"type\":\"paragraph\",\"data\":{\"text\":\"The final walkthrough takes place prior to the work completion where we perform a quality check together with you\"}}],\"version\":\"2.22.2\"}','2021-06-08 09:34:42','2022-02-09 04:29:53',NULL,0),(12,NULL,7,6,NULL,'Done!',NULL,NULL,NULL,'{\"time\":1644381179544,\"blocks\":[{\"id\":\"6Pgh4EnUkC\",\"type\":\"paragraph\",\"data\":{\"text\":\"Your smile at the end is what we do this for.&nbsp;\"}}],\"version\":\"2.22.2\"}','2021-06-08 09:35:55','2022-02-09 04:33:01',NULL,0),(13,NULL,8,1,NULL,'Have a project in mind?',NULL,NULL,NULL,'{\"time\":1641228369314,\"blocks\":[{\"id\":\"Jc3I1VJTDM\",\"type\":\"paragraph\",\"data\":{\"text\":\"It\'s easy to get started\"}}],\"version\":\"2.22.2\"}','2021-06-08 17:33:03','2022-02-09 03:40:24','2022-02-09 03:40:24',0),(14,NULL,8,1,NULL,'Request an Estimate','Scope',NULL,NULL,'{\"time\":1713976227580,\"blocks\":[{\"id\":\"gIDvdfQNC2\",\"type\":\"paragraph\",\"data\":{\"text\":\"Submit the&nbsp;<a href=\\\"https://moderncitigroup.com/initial-form/works\\\" target=\\\"_blank\\\">project form</a>&nbsp;and tell us about your remodeling goals.\"}}],\"version\":\"2.23.2\"}','2021-06-08 17:33:42','2024-04-24 16:30:28',NULL,0),(15,NULL,8,2,NULL,'Meet your Renovation Team','Plan',NULL,NULL,'{\"time\":1660251607888,\"blocks\":[{\"id\":\"bmKr2kkBlt\",\"type\":\"paragraph\",\"data\":{\"text\":\"Schedule your at-home visit and meet your renovation team.\"}}],\"version\":\"2.23.2\"}','2021-06-08 17:34:11','2022-08-11 21:00:07',NULL,0),(16,NULL,8,3,NULL,'Design and Select Your Materials','Design',NULL,NULL,'{\"time\":1660414820356,\"blocks\":[{\"id\":\"9G_JdTAYx1\",\"type\":\"paragraph\",\"data\":{\"text\":\"Choose <a href=\\\"https://moderncitigroup.com/ready-solutions\\\" target=\\\"_blank\\\">a ready solution</a> or hand-pick materials with the help of an interior designer.\"}}],\"version\":\"2.23.2\"}','2021-06-08 17:34:34','2022-08-13 18:20:20',NULL,0),(17,NULL,8,5,NULL,'Check your Project Dashboard','Prepare',NULL,NULL,'{\"time\":1660251614715,\"blocks\":[{\"id\":\"8zl8IiKWE5\",\"type\":\"paragraph\",\"data\":{\"text\":\"While we prepare the permits and plans, you can check your project dashboard for daily status updates.\"}}],\"version\":\"2.23.2\"}','2021-06-08 17:35:03','2022-08-11 21:00:14',NULL,0),(18,NULL,8,5,NULL,'Let the Building Begin','Build',NULL,NULL,'{\"time\":1660251622655,\"blocks\":[{\"id\":\"7abwld-n0g\",\"type\":\"paragraph\",\"data\":{\"text\":\"Sit back as the work begins. Your renovation team will handle everything so you don’t have to.\"}}],\"version\":\"2.23.2\"}','2021-06-08 17:35:30','2022-08-11 21:00:22',NULL,0),(19,NULL,8,6,NULL,'Permits & Approvals',NULL,NULL,NULL,'{\"time\":1641227215681,\"blocks\":[{\"id\":\"3Bc2ftjiHi\",\"type\":\"paragraph\",\"data\":{\"text\":\"We will prepare all required documents, drawings, permits for the official work approval\"}}],\"version\":\"2.22.2\"}','2021-06-08 17:35:53','2022-02-09 04:02:20','2022-02-09 04:02:20',0),(20,N