INSERT INTO `static_pages` VALUES (1,'Terms of use','terms-of-use','/terms','Terms of use','Terms of use desc','{\"time\":1637885561366,\"blocks\":[{\"id\":\"BY3RJrw8Ai\",\"type\":\"paragraph\",\"data\":{\"text\":\"THESE TERMS GOVERN\"}},{\"id\":\"oSrG548jdP\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[\"THE USE OF THIS WEBSITE, AND,\",\"ANY OTHER RELATED AGREEMENT OR LEGAL RELATIONSHIP WITH THE OWNER IN A LEGALLY BINDING WAY.\"]}},{\"id\":\"XYZuqIpUu4\",\"type\":\"paragraph\",\"data\":{\"text\":\"CAPITALIZED WORDS ARE DEFINED IN THE RELEVANT DEDICATED SECTION OF THIS DOCUMENT.\"}},{\"id\":\"txet6_C4ti\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE USER MUST READ THIS DOCUMENT CAREFULLY.\"}},{\"id\":\"iSi69XyNeL\",\"type\":\"paragraph\",\"data\":{\"text\":\"NOTHING IN THESE TERMS CREATES ANY RELATIONSHIP OF EMPLOYMENT, AGENCY, OR PARTNERSHIP BETWEEN THE INVOLVED PARTIES.\"}},{\"id\":\"kz27842Td3\",\"type\":\"paragraph\",\"data\":{\"text\":\"THIS WEBSITE IS PROVIDED BY:\"}},{\"id\":\"tA88naDaoa\",\"type\":\"paragraph\",\"data\":{\"text\":\"MODERN CITI GROUP INC., 1572 DAHILL ROAD, BROOKLYN, NY 11204\"}},{\"id\":\"TfV6iatg4w\",\"type\":\"paragraph\",\"data\":{\"text\":\"OWNER CONTACT EMAIL: CONTACT@MODERNCITIGROUP.COM\"}},{\"id\":\"z0fQwm9jUD\",\"type\":\"paragraph\",\"data\":{\"text\":\"TELEPHONE NUMBER: (844) 624 0044 (HEREINAFTER THE “OWNER”)\"}},{\"id\":\"NOKOMp1V9x\",\"type\":\"paragraph\",\"data\":{\"text\":\"INFORMATION ABOUT THIS WEBSITE:\"}},{\"id\":\"_HNXu1w4qA\",\"type\":\"paragraph\",\"data\":{\"text\":\"LICENSED GENERAL CONTRACTOR - NEW YORK, NEW JERSEY, FLORIDA. RENOVATION, REMODELING, ARCHITECTURE, DESIGN.\"}},{\"id\":\"rCcDgAEDEb\",\"type\":\"paragraph\",\"data\":{\"text\":\"WHAT THE USER SHOULD KNOW AT A GLANCE\"}},{\"id\":\"J1J3LP9h50\",\"type\":\"paragraph\",\"data\":{\"text\":\"PLEASE NOTE THAT SOME PROVISIONS IN THESE TERMS MAY ONLY APPLY TO CERTAIN CATEGORIES OF USERS. IN PARTICULAR, CERTAIN PROVISIONS MAY ONLY APPLY TO CONSUMERS OR TO THOSE USERS THAT DO NOT QUALIFY AS CONSUMERS. SUCH LIMITATIONS ARE ALWAYS EXPLICITLY MENTIONED WITHIN EACH AFFECTED CLAUSE. IN THE ABSENCE OF ANY SUCH MENTION, CLAUSES APPLY TO ALL USERS.\"}},{\"id\":\"qfh9AlfBED\",\"type\":\"paragraph\",\"data\":{\"text\":\"TERMS OF USE\"}},{\"id\":\"LblWM5OFUP\",\"type\":\"paragraph\",\"data\":{\"text\":\"UNLESS OTHERWISE SPECIFIED, THE TERMS OF USE DETAILED IN THIS SECTION APPLY GENERALLY WHEN USING THIS WEBSITE.&nbsp;\"}},{\"id\":\"t_JFJXcAwC\",\"type\":\"paragraph\",\"data\":{\"text\":\"SINGLE OR ADDITIONAL CONDITIONS OF USE OR ACCESS MAY APPLY IN SPECIFIC SCENARIOS AND IN SUCH CASES ARE ADDITIONALLY INDICATED WITHIN THIS DOCUMENT.BY USING THIS WEBSITE, USERS CONFIRM TO MEET THE FOLLOWING REQUIREMENTS:\"}},{\"id\":\"7tUsPkC17p\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[\"THERE ARE NO RESTRICTIONS FOR USERS IN TERMS OF BEING CONSUMERS OR BUSINESS USERS.\"]}},{\"id\":\"Dj1AnhoT2n\",\"type\":\"paragraph\",\"data\":{\"text\":\"CONTENT ON THIS WEBSITE\"}},{\"id\":\"G0MBvgx9bA\",\"type\":\"paragraph\",\"data\":{\"text\":\"UNLESS WHERE OTHERWISE SPECIFIED OR CLEARLY RECOGNIZABLE, ALL CONTENT AVAILABLE ON THIS WEBSITE IS OWNED OR PROVIDED BY THE OWNER OR ITS LICENSORS.\"}},{\"id\":\"BuJ7SDN_qU\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE OWNER UNDERTAKES ITS UTMOST EFFORT TO ENSURE THAT THE CONTENT PROVIDED ON THIS WEBSITE INFRINGES NO APPLICABLE LEGAL PROVISIONS OR THIRD-PARTY RIGHTS. HOWEVER, IT MAY NOT ALWAYS BE POSSIBLE TO ACHIEVE SUCH A RESULT.\"}},{\"id\":\"T38hc3EQ-l\",\"type\":\"paragraph\",\"data\":{\"text\":\"IN SUCH CASES, WITHOUT PREJUDICE TO ANY LEGAL PREROGATIVES OF USERS TO ENFORCE THEIR RIGHTS, USERS ARE KINDLY ASKED TO PREFERABLY REPORT RELATED COMPLAINTS USING THE CONTACT DETAILS PROVIDED IN THIS DOCUMENT.\"}},{\"id\":\"o9ah38f25j\",\"type\":\"paragraph\",\"data\":{\"text\":\"RIGHTS REGARDING CONTENT ON THIS WEBSITE - ALL RIGHTS RESERVED\"}},{\"id\":\"I9nTDrxNz0\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE OWNER HOLDS AND RESERVES ALL INTELLECTUAL PROPERTY RIGHTS FOR ANY SUCH CONTENT.\"}},{\"id\":\"LFwJRrfLht\",\"type\":\"paragraph\",\"data\":{\"text\":\"USERS MAY NOT THEREFORE USE SUCH CONTENT IN ANY WAY THAT IS NOT NECESSARY OR IMPLICIT IN THE PROPER USE OF THE SERVICE.\"}},{\"id\":\"wKAS3hrQOy\",\"type\":\"paragraph\",\"data\":{\"text\":\"IN PARTICULAR, BUT WITHOUT LIMITATION, USERS MAY NOT COPY, DOWNLOAD, SHARE (BEYOND THE LIMITS SET FORTH BELOW), MODIFY, TRANSLATE, TRANSFORM, PUBLISH, TRANSMIT, SELL, SUBLICENSE, EDIT, TRANSFER/ASSIGN TO THIRD PARTIES OR CREATE DERIVATIVE WORKS FROM THE CONTENT AVAILABLE ON THIS WEBSITE, NOR ALLOW ANY THIRD PARTY TO DO SO THROUGH THE USER OR THEIR DEVICE, EVEN WITHOUT THE USER\'S KNOWLEDGE.\"}},{\"id\":\"X1E5MNcYAF\",\"type\":\"paragraph\",\"data\":{\"text\":\"WHERE EXPLICITLY STATED ON THIS WEBSITE, THE USER MAY DOWNLOAD, COPY AND/OR SHARE SOME CONTENT AVAILABLE THROUGH THIS WEBSITE FOR ITS SOLE PERSONAL AND NON-COMMERCIAL USE AND PROVIDED THAT THE COPYRIGHT ATTRIBUTIONS AND ALL THE OTHER ATTRIBUTIONS REQUESTED BY THE OWNER ARE CORRECTLY IMPLEMENTED.\"}},{\"id\":\"E6WXInxv_C\",\"type\":\"paragraph\",\"data\":{\"text\":\"ANY APPLICABLE STATUTORY LIMITATION OR EXCEPTION TO COPYRIGHT SHALL STAY UNAFFECTED.\"}},{\"id\":\"AHoIVG1pmm\",\"type\":\"paragraph\",\"data\":{\"text\":\"ACCESS TO EXTERNAL RESOURCES\"}},{\"id\":\"fDujGuweGX\",\"type\":\"paragraph\",\"data\":{\"text\":\"THROUGH THIS WEBSITE USERS MAY HAVE ACCESS TO EXTERNAL RESOURCES PROVIDED BY THIRD PARTIES. USERS ACKNOWLEDGE AND ACCEPT THAT THE OWNER HAS NO CONTROL OVER SUCH RESOURCES AND IS THEREFORE NOT RESPONSIBLE FOR THEIR CONTENT AND AVAILABILITY.\"}},{\"id\":\"zVzV9b0Apn\",\"type\":\"paragraph\",\"data\":{\"text\":\"CONDITIONS APPLICABLE TO ANY RESOURCES PROVIDED BY THIRD PARTIES, INCLUDING THOSE APPLICABLE TO ANY POSSIBLE GRANT OF RIGHTS IN CONTENT, RESULT FROM EACH SUCH THIRD PARTIES’ TERMS AND CONDITIONS OR, IN THE ABSENCE OF THOSE, APPLICABLE STATUTORY LAW.\"}},{\"id\":\"Jcle9teC4P\",\"type\":\"paragraph\",\"data\":{\"text\":\"ACCEPTABLE USE\"}},{\"id\":\"Py6TVKm6x3\",\"type\":\"paragraph\",\"data\":{\"text\":\"THIS WEBSITE AND THE SERVICE MAY ONLY BE USED WITHIN THE SCOPE OF WHAT THEY ARE PROVIDED FOR, UNDER THESE TERMS AND APPLICABLE LAW.\"}},{\"id\":\"Y6_6eY1tRv\",\"type\":\"paragraph\",\"data\":{\"text\":\"USERS ARE SOLELY RESPONSIBLE FOR MAKING SURE THAT THEIR USE OF THIS WEBSITE AND/OR THE SERVICE VIOLATES NO APPLICABLE LAW, REGULATIONS OR THIRD-PARTY RIGHTS.\"}},{\"id\":\"RVzNSz-Ew6\",\"type\":\"paragraph\",\"data\":{\"text\":\"THEREFORE, THE OWNER RESERVES THE RIGHT TO TAKE ANY APPROPRIATE MEASURE TO PROTECT ITS LEGITIMATE INTERESTS INCLUDING BY DENYING USERS ACCESS TO THIS WEBSITE OR THE SERVICE, TERMINATING CONTRACTS, REPORTING ANY MISCONDUCT PERFORMED THROUGH THIS WEBSITE OR THE SERVICE TO THE COMPETENT AUTHORITIES – SUCH AS JUDICIAL OR ADMINISTRATIVE AUTHORITIES - WHENEVER USERS ENGAGE OR ARE SUSPECTED TO ENGAGE IN ANY OF THE FOLLOWING ACTIVITIES:\"}},{\"id\":\"pTCZ619Zh4\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[\"&nbsp;VIOLATE LAWS, REGULATIONS AND/OR THESE TERMS;\",\"INFRINGE ANY THIRD-PARTY RIGHTS;\",\"CONSIDERABLY IMPAIR THE OWNER’S LEGITIMATE INTERESTS;\",\"OFFEND THE OWNER OR ANY THIRD PARTY.\"]}},{\"id\":\"zm8dzlpNpE\",\"type\":\"paragraph\",\"data\":{\"text\":\"SOFTWARE LICENSE\"}},{\"id\":\"RCkoJUMymT\",\"type\":\"paragraph\",\"data\":{\"text\":\"ANY INTELLECTUAL OR INDUSTRIAL PROPERTY RIGHTS, AND ANY OTHER EXCLUSIVE RIGHTS ON SOFTWARE OR TECHNICAL APPLICATIONS EMBEDDED IN OR RELATED TO THIS WEBSITE ARE HELD BY THE OWNER AND/OR ITS LICENSORS.\"}},{\"id\":\"SURQi1gkYc\",\"type\":\"paragraph\",\"data\":{\"text\":\"SUBJECT TO USERS’ COMPLIANCE WITH AND NOTWITHSTANDING ANY DIVERGENT PROVISION OF THESE TERMS, THE OWNER MERELY GRANTS USERS A REVOCABLE, NON-EXCLUSIVE, NON-SUBLICENSABLE AND NON-TRANSFERABLE LICENSE TO USE THE SOFTWARE AND/OR ANY OTHER TECHNICAL MEANS EMBEDDED IN THE SERVICE WITHIN THE SCOPE AND FOR THE PURPOSES OF THIS WEBSITE AND THE SERVICE OFFERED.\"}},{\"id\":\"gSiJr1vX8k\",\"type\":\"paragraph\",\"data\":{\"text\":\"THIS LICENSE DOES NOT GRANT USERS ANY RIGHTS TO ACCESS, USAGE OR DISCLOSURE OF THE ORIGINAL SOURCE CODE. ALL TECHNIQUES, ALGORITHMS, AND PROCEDURES CONTAINED IN THE SOFTWARE AND ANY DOCUMENTATION THERETO RELATED IS THE OWNER’S OR ITS LICENSORS’ SOLE PROPERTY.\"}},{\"id\":\"vUM0pCDOUG\",\"type\":\"paragraph\",\"data\":{\"text\":\"ALL RIGHTS AND LICENSE GRANTS TO USERS SHALL IMMEDIATELY TERMINATE UPON ANY TERMINATION OR EXPIRATION OF THE AGREEMENT.\"}},{\"id\":\"3VDXj7Hha0\",\"type\":\"paragraph\",\"data\":{\"text\":\"LIABILITY AND INDEMNIFICATION\"}},{\"id\":\"ZIZilLuhq0\",\"type\":\"paragraph\",\"data\":{\"text\":\"DISCLAIMER OF WARRANTIES\"}},{\"id\":\"VyeqZ2dlbf\",\"type\":\"paragraph\",\"data\":{\"text\":\"THIS WEBSITE IS PROVIDED STRICTLY ON AN “AS IS” AND “AS AVAILABLE” BASIS. USE OF THE SERVICE IS AT USERS’ OWN RISK. TO THE MAXIMUM EXTENT PERMITTED BY APPLICABLE LAW, THE OWNER EXPRESSLY DISCLAIMS ALL CONDITIONS, REPRESENTATIONS, AND WARRANTIES — WHETHER EXPRESS, IMPLIED, STATUTORY OR OTHERWISE, INCLUDING, BUT NOT LIMITED TO, ANY IMPLIED WARRANTY OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE, OR NON-INFRINGEMENT OF THIRD-PARTY RIGHTS. NO ADVICE OR INFORMATION, WHETHER ORAL OR WRITTEN, OBTAINED BY USER FROM OWNER OR THROUGH THE SERVICE WILL CREATE ANY WARRANTY NOT EXPRESSLY STATED HEREIN.\"}},{\"id\":\"m1RVZglO9Y\",\"type\":\"paragraph\",\"data\":{\"text\":\"WITHOUT LIMITING THE FOREGOING, THE OWNER, ITS SUBSIDIARIES, AFFILIATES, LICENSORS, OFFICERS, DIRECTORS, AGENTS, CO-BRANDERS, PARTNERS, SUPPLIERS AND EMPLOYEES DO NOT WARRANT THAT THE CONTENT IS ACCURATE, RELIABLE OR CORRECT; THAT THE SERVICE WILL MEET USERS’ REQUIREMENTS; THAT THE SERVICE WILL BE AVAILABLE AT ANY PARTICULAR TIME OR LOCATION, UNINTERRUPTED OR SECURE; THAT ANY DEFECTS OR ERRORS WILL BE CORRECTED; OR THAT THE SERVICE IS FREE OF VIRUSES OR OTHER HARMFUL COMPONENTS. ANY CONTENT DOWNLOADED OR OTHERWISE OBTAINED THROUGH THE USE OF THE SERVICE IS DOWNLOADED AT USERS OWN RISK AND USERS SHALL BE SOLELY RESPONSIBLE FOR ANY DAMAGE TO USERS’ COMPUTER SYSTEM OR MOBILE DEVICE OR LOSS OF DATA THAT RESULTS FROM SUCH DOWNLOAD OR USERS’ USE OF THE SERVICE.\"}},{\"id\":\"YzDSIWXs4g\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE OWNER DOES NOT WARRANT, ENDORSE, GUARANTEE, OR ASSUME RESPONSIBILITY FOR ANY PRODUCT OR SERVICE ADVERTISED OR OFFERED BY A THIRD PARTY THROUGH THE SERVICE OR ANY HYPERLINKED WEBSITE OR SERVICE, AND THE OWNER SHALL NOT BE A PARTY TO OR IN ANY WAY MONITOR ANY TRANSACTION BETWEEN USERS AND THIRD-PARTY PROVIDERS OF PRODUCTS OR SERVICES.\"}},{\"id\":\"YUfrFZIeRb\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE SERVICE MAY BECOME INACCESSIBLE OR IT MAY NOT FUNCTION PROPERLY WITH USERS’ WEB BROWSER, MOBILE DEVICE, AND/OR OPERATING SYSTEM. THE OWNER CANNOT BE HELD LIABLE FOR ANY PERCEIVED OR ACTUAL DAMAGES ARISING FROM SERVICE CONTENT, OPERATION, OR USE OF THIS SERVICE.\"}},{\"id\":\"HNL3ASimMm\",\"type\":\"paragraph\",\"data\":{\"text\":\"FEDERAL LAW, SOME STATES, AND OTHER JURISDICTIONS, DO NOT ALLOW THE EXCLUSION AND LIMITATIONS OF CERTAIN IMPLIED WARRANTIES. THE ABOVE EXCLUSIONS MAY NOT APPLY TO USERS. THIS AGREEMENT GIVES USERS SPECIFIC LEGAL RIGHTS, AND USERS MAY ALSO HAVE OTHER RIGHTS WHICH VARY FROM STATE TO STATE. THE DISCLAIMERS AND EXCLUSIONS UNDER THIS AGREEMENT SHALL NOT APPLY TO THE EXTENT PROHIBITED BY APPLICABLE LAW.\"}},{\"id\":\"bH3B284TRf\",\"type\":\"paragraph\",\"data\":{\"text\":\"LIMITATIONS OF LIABILITY\"}},{\"id\":\"832gP8cPZ4\",\"type\":\"paragraph\",\"data\":{\"text\":\"TO THE MAXIMUM EXTENT PERMITTED BY APPLICABLE LAW, IN NO EVENT SHALL THE OWNER, AND ITS SUBSIDIARIES, AFFILIATES, OFFICERS, DIRECTORS, AGENTS, CO-BRANDERS, PARTNERS, SUPPLIERS AND EMPLOYEES BE LIABLE FOR\"}},{\"id\":\"9r8kSQqdp8\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[\"ANY INDIRECT, PUNITIVE, INCIDENTAL, SPECIAL, CONSEQUENTIAL OR EXEMPLARY DAMAGES, INCLUDING WITHOUT LIMITATION DAMAGES FOR LOSS OF PROFITS, GOODWILL, USE, DATA OR OTHER INTANGIBLE LOSSES, ARISING OUT OF OR RELATING TO THE USE OF, OR INABILITY TO USE, THE SERVICE; AND\",\"ANY DAMAGE, LOSS OR INJURY RESULTING FROM HACKING, TAMPERING OR OTHER UNAUTHORIZED ACCESS OR USE OF THE SERVICE OR USER ACCOUNT OR THE INFORMATION CONTAINED THEREIN;\",\"ANY ERRORS, MISTAKES, OR INACCURACIES OF CONTENT;\",\"PERSONAL INJURY OR PROPERTY DAMAGE, OF ANY NATURE WHATSOEVER, RESULTING FROM USER ACCESS TO OR USE OF THE SERVICE;\",\"ANY UNAUTHORIZED ACCESS TO OR USE OF THE OWNER’S SECURE SERVERS AND/OR ANY AND ALL PERSONAL INFORMATION STORED THEREIN;\",\"ANY INTERRUPTION OR CESSATION OF TRANSMISSION TO OR FROM THE SERVICE;\",\"ANY BUGS, VIRUSES, TROJAN HORSES, OR THE LIKE THAT MAY BE TRANSMITTED TO OR THROUGH THE SERVICE;\",\"ANY ERRORS OR OMISSIONS IN ANY CONTENT OR FOR ANY LOSS OR DAMAGE INCURRED AS A RESULT OF THE USE OF ANY CONTENT POSTED, EMAILED, TRANSMITTED, OR OTHERWISE MADE AVAILABLE THROUGH THE SERVICE; AND/OR\",\"THE DEFAMATORY, OFFENSIVE, OR ILLEGAL CONDUCT OF ANY USER OR THIRD PARTY. IN NO EVENT SHALL THE OWNER, AND ITS SUBSIDIARIES, AFFILIATES, OFFICERS, DIRECTORS, AGENTS, CO-BRANDERS, PARTNERS, SUPPLIERS AND EMPLOYEES BE LIABLE FOR ANY CLAIMS, PROCEEDINGS, LIABILITIES, OBLIGATIONS, DAMAGES, LOSSES OR COSTS IN AN AMOUNT EXCEEDING THE AMOUNT PAID BY USER TO THE OWNER HEREUNDER IN THE PRECEDING 12 MONTHS, OR THE PERIOD OF DURATION OF THIS AGREEMENT BETWEEN THE OWNER AND USER, WHICHEVER IS SHORTER.\"]}},{\"id\":\"umrbHInHpG\",\"type\":\"paragraph\",\"data\":{\"text\":\"THIS LIMITATION OF LIABILITY SECTION SHALL APPLY TO THE FULLEST EXTENT PERMITTED BY LAW IN THE APPLICABLE JURISDICTION WHETHER THE ALLEGED LIABILITY IS BASED ON CONTRACT, TORT, NEGLIGENCE, STRICT LIABILITY, OR ANY OTHER BASIS, EVEN IF COMPANY HAS BEEN ADVISED OF THE POSSIBILITY OF SUCH DAMAGE.\"}},{\"id\":\"hpHpKwZihe\",\"type\":\"paragraph\",\"data\":{\"text\":\"SOME JURISDICTIONS DO NOT ALLOW THE EXCLUSION OR LIMITATION OF INCIDENTAL OR CONSEQUENTIAL DAMAGES, THEREFORE THE ABOVE LIMITATIONS OR EXCLUSIONS MAY NOT APPLY TO USER. THE TERMS GIVE USER SPECIFIC LEGAL RIGHTS, AND USER MAY ALSO HAVE OTHER RIGHTS WHICH VARY FROM JURISDICTION TO JURISDICTION. THE DISCLAIMERS, EXCLUSIONS, AND LIMITATIONS OF LIABILITY UNDER THE TERMS SHALL NOT APPLY TO THE EXTENT PROHIBITED BY APPLICABLE LAW.\"}},{\"id\":\"CPL-y6G0it\",\"type\":\"paragraph\",\"data\":{\"text\":\"INDEMNIFICATION\"}},{\"id\":\"KNANaaRW2h\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE USER AGREES TO DEFEND, INDEMNIFY AND HOLD THE OWNER AND ITS SUBSIDIARIES, AFFILIATES, OFFICERS, DIRECTORS, AGENTS, CO-BRANDERS, PARTNERS, SUPPLIERS AND EMPLOYEES HARMLESS FROM AND AGAINST ANY AND ALL CLAIMS OR DEMANDS, DAMAGES, OBLIGATIONS, LOSSES, LIABILITIES, COSTS OR DEBT, AND EXPENSES, INCLUDING, BUT NOT LIMITED TO, LEGAL FEES AND EXPENSES, ARISING FROM\"}},{\"id\":\"Qf5ydOxTQP\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[\"USER’S USE OF AND ACCESS TO THE SERVICE, INCLUDING ANY DATA OR CONTENT TRANSMITTED OR RECEIVED BY USER;\",\"USER’S VIOLATION OF THESE TERMS, INCLUDING, BUT NOT LIMITED TO, USER’S BREACH OF ANY OF THE REPRESENTATIONS AND WARRANTIES SET FORTH IN THESE TERMS;\",\"USER’S VIOLATION OF ANY THIRD-PARTY RIGHTS, INCLUDING, BUT NOT LIMITED TO, ANY RIGHT OF PRIVACY OR INTELLECTUAL PROPERTY RIGHTS;\",\"USER’S VIOLATION OF ANY STATUTORY LAW, RULE, OR REGULATION;\",\"ANY CONTENT THAT IS SUBMITTED FROM USER’S ACCOUNT, INCLUDING THIRD PARTY ACCESS WITH USER’S UNIQUE USERNAME, PASSWORD OR OTHER SECURITY MEASURE, IF APPLICABLE, INCLUDING, BUT NOT LIMITED TO, MISLEADING, FALSE, OR INACCURATE INFORMATION;\",\"USER’S WILFUL MISCONDUCT; OR\",\"STATUTORY PROVISION BY USER OR ITS AFFILIATES, OFFICERS, DIRECTORS, AGENTS, CO-BRANDERS, PARTNERS, SUPPLIERS AND EMPLOYEES TO THE EXTENT ALLOWED BY APPLICABLE LAW.\"]}},{\"id\":\"YXDBKA6A7Q\",\"type\":\"paragraph\",\"data\":{\"text\":\"COMMON PROVISIONS\"}},{\"id\":\"KvWErKfuQJ\",\"type\":\"paragraph\",\"data\":{\"text\":\"NO WAIVER\"}},{\"id\":\"iyqs8__mpt\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE OWNER’S FAILURE TO ASSERT ANY RIGHT OR PROVISION UNDER THESE TERMS SHALL NOT CONSTITUTE A WAIVER OF ANY SUCH RIGHT OR PROVISION. NO WAIVER SHALL BE CONSIDERED A FURTHER OR CONTINUING WAIVER OF SUCH TERM OR ANY OTHER TERM.\"}},{\"id\":\"ZMYaVJWqbe\",\"type\":\"paragraph\",\"data\":{\"text\":\"SERVICE INTERRUPTION\"}},{\"id\":\"h9pPg0_zRy\",\"type\":\"paragraph\",\"data\":{\"text\":\"TO ENSURE THE BEST POSSIBLE SERVICE LEVEL, THE OWNER RESERVES THE RIGHT TO INTERRUPT THE SERVICE FOR MAINTENANCE, SYSTEM UPDATES OR ANY OTHER CHANGES, INFORMING THE USERS APPROPRIATELY.\"}},{\"id\":\"d3bAPj_1yD\",\"type\":\"paragraph\",\"data\":{\"text\":\"WITHIN THE LIMITS OF LAW, THE OWNER MAY ALSO DECIDE TO SUSPEND OR TERMINATE THE SERVICE ALTOGETHER. IF THE SERVICE IS TERMINATED, THE OWNER WILL COOPERATE WITH USERS TO ENABLE THEM TO WITHDRAW PERSONAL DATA OR INFORMATION IN ACCORDANCE WITH APPLICABLE LAW.\"}},{\"id\":\"mzb2kPAd0X\",\"type\":\"paragraph\",\"data\":{\"text\":\"ADDITIONALLY, THE SERVICE MIGHT NOT BE AVAILABLE DUE TO REASONS OUTSIDE THE OWNER’S REASONABLE CONTROL, SUCH AS “FORCE MAJEURE” (EG. LABOR ACTIONS, INFRASTRUCTURAL BREAKDOWNS OR BLACKOUTS ETC).\"}},{\"id\":\"ABwt3JirBV\",\"type\":\"paragraph\",\"data\":{\"text\":\"SERVICE RESELLING\"}},{\"id\":\"807CO6jIEt\",\"type\":\"paragraph\",\"data\":{\"text\":\"USERS MAY NOT REPRODUCE, DUPLICATE, COPY, SELL, RESELL OR EXPLOIT ANY PORTION OF THIS WEBSITE AND OF ITS SERVICE WITHOUT THE OWNER’S EXPRESS PRIOR WRITTEN PERMISSION, GRANTED EITHER DIRECTLY OR THROUGH A LEGITIMATE RESELLING PROGRAMME.\"}},{\"id\":\"qpXD11ESxx\",\"type\":\"paragraph\",\"data\":{\"text\":\"PRIVACY POLICY\"}},{\"id\":\"gKmdcHjEKa\",\"type\":\"paragraph\",\"data\":{\"text\":\"TO LEARN MORE ABOUT THE USE OF THEIR PERSONAL DATA, USERS MAY REFER TO THE PRIVACY POLICY OF THIS WEBSITE.\"}},{\"id\":\"vNg8m_uVTY\",\"type\":\"paragraph\",\"data\":{\"text\":\"INTELLECTUAL PROPERTY RIGHTS\"}},{\"id\":\"-RaaNPoxRZ\",\"type\":\"paragraph\",\"data\":{\"text\":\"WITHOUT PREJUDICE TO ANY MORE SPECIFIC PROVISION OF THESE TERMS, ANY INTELLECTUAL PROPERTY RIGHTS, SUCH AS COPYRIGHTS, TRADEMARK RIGHTS, PATENT RIGHTS AND DESIGN RIGHTS RELATED TO THIS WEBSITE ARE THE EXCLUSIVE PROPERTY OF THE OWNER OR ITS LICENSORS AND ARE SUBJECT TO THE PROTECTION GRANTED BY APPLICABLE LAWS OR INTERNATIONAL TREATIES RELATING TO INTELLECTUAL PROPERTY.\"}},{\"id\":\"fryaM3JMF2\",\"type\":\"paragraph\",\"data\":{\"text\":\"ALL TRADEMARKS — NOMINAL OR FIGURATIVE — AND ALL OTHER MARKS, TRADE NAMES, SERVICE MARKS, WORD MARKS, ILLUSTRATIONS, IMAGES, OR LOGOS APPEARING IN CONNECTION WITH THIS WEBSITE ARE, AND REMAIN, THE EXCLUSIVE PROPERTY OF THE OWNER OR ITS LICENSORS AND ARE SUBJECT TO THE PROTECTION GRANTED BY APPLICABLE LAWS OR INTERNATIONAL TREATIES RELATED TO INTELLECTUAL PROPERTY.\"}},{\"id\":\"YE5ms52Qrt\",\"type\":\"paragraph\",\"data\":{\"text\":\"CHANGES TO THESE TERMS\"}},{\"id\":\"NATbXl4QbS\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE OWNER RESERVES THE RIGHT TO AMEND OR OTHERWISE MODIFY THESE TERMS AT ANY TIME. IN SUCH CASES, THE OWNER WILL APPROPRIATELY INFORM THE USER OF THESE CHANGES.\"}},{\"id\":\"_zzSgUEOEf\",\"type\":\"paragraph\",\"data\":{\"text\":\"SUCH CHANGES WILL ONLY AFFECT THE RELATIONSHIP WITH THE USER FOR THE FUTURE.\"}},{\"id\":\"KQJASp-dtq\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE CONTINUED USE OF THE SERVICE WILL SIGNIFY THE USER’S ACCEPTANCE OF THE REVISED TERMS. IF USERS DO NOT WISH TO BE BOUND BY THE CHANGES, THEY MUST STOP USING THE SERVICE. FAILURE TO ACCEPT THE REVISED TERMS, MAY ENTITLE EITHER PARTY TO TERMINATE THE AGREEMENT.\"}},{\"id\":\"opz-gl6jaV\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE APPLICABLE PREVIOUS VERSION WILL GOVERN THE RELATIONSHIP PRIOR TO THE USER\'S ACCEPTANCE. THE USER CAN OBTAIN ANY PREVIOUS VERSION FROM THE OWNER.\"}},{\"id\":\"SnQzC3HX8G\",\"type\":\"paragraph\",\"data\":{\"text\":\"IF REQUIRED BY APPLICABLE LAW, THE OWNER WILL SPECIFY THE DATE BY WHICH THE MODIFIED TERMS WILL ENTER INTO FORCE.\"}},{\"id\":\"Ef985jCpCe\",\"type\":\"paragraph\",\"data\":{\"text\":\"ASSIGNMENT OF CONTRACT\"}},{\"id\":\"EAkRpaa4n6\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE OWNER RESERVES THE RIGHT TO TRANSFER, ASSIGN, DISPOSE OF BY NOVATION, OR SUBCONTRACT ANY OR ALL RIGHTS OR OBLIGATIONS UNDER THESE TERMS, TAKING THE USER’S LEGITIMATE INTERESTS INTO ACCOUNT. PROVISIONS REGARDING CHANGES OF THESE TERMS WILL APPLY ACCORDINGLY.\"}},{\"id\":\"LyDES8jB3M\",\"type\":\"paragraph\",\"data\":{\"text\":\"USERS MAY NOT ASSIGN OR TRANSFER THEIR RIGHTS OR OBLIGATIONS UNDER THESE TERMS IN ANY WAY, WITHOUT THE WRITTEN PERMISSION OF THE OWNER.\"}},{\"id\":\"08zdmXCgPA\",\"type\":\"paragraph\",\"data\":{\"text\":\"CONTACTS\"}},{\"id\":\"aSqy7uKznz\",\"type\":\"paragraph\",\"data\":{\"text\":\"ALL COMMUNICATIONS RELATING TO THE USE OF THIS WEBSITE MUST BE SENT USING THE CONTACT INFORMATION STATED IN THIS DOCUMENT.\"}},{\"id\":\"OvpsrXji6f\",\"type\":\"paragraph\",\"data\":{\"text\":\"SEVERABILITY\"}},{\"id\":\"5MddiU0UHP\",\"type\":\"paragraph\",\"data\":{\"text\":\"SHOULD ANY PROVISION OF THESE TERMS BE DEEMED OR BECOME INVALID OR UNENFORCEABLE UNDER APPLICABLE LAW, THE INVALIDITY OR UNENFORCEABILITY OF SUCH PROVISION SHALL NOT AFFECT THE VALIDITY OF THE REMAINING PROVISIONS, WHICH SHALL REMAIN IN FULL FORCE AND EFFECT.\"}},{\"id\":\"AMOegqVFbl\",\"type\":\"paragraph\",\"data\":{\"text\":\"USERS\"}},{\"id\":\"3Ce361P6zq\",\"type\":\"paragraph\",\"data\":{\"text\":\"ANY SUCH INVALID OR UNENFORCEABLE PROVISION WILL BE INTERPRETED, CONSTRUED AND REFORMED TO THE EXTENT REASONABLY REQUIRED TO RENDER IT VALID, ENFORCEABLE AND CONSISTENT WITH ITS ORIGINAL INTENT. THESE TERMS CONSTITUTE THE ENTIRE AGREEMENT BETWEEN USERS AND THE OWNER WITH RESPECT TO THE SUBJECT MATTER HEREOF, AND SUPERSEDE ALL OTHER COMMUNICATIONS, INCLUDING BUT NOT LIMITED TO ALL PRIOR AGREEMENTS, BETWEEN THE PARTIES WITH RESPECT TO SUCH SUBJECT MATTER. THESE TERMS WILL BE ENFORCED TO THE FULLEST EXTENT PERMITTED BY LAW.\"}},{\"id\":\"F0RF3yx43o\",\"type\":\"paragraph\",\"data\":{\"text\":\"GOVERNING LAW\"}},{\"id\":\"70-0FfMonO\",\"type\":\"paragraph\",\"data\":{\"text\":\"THESE TERMS ARE GOVERNED BY THE LAW OF THE PLACE WHERE THE OWNER IS BASED, AS DISCLOSED IN THE RELEVANT SECTION OF THIS DOCUMENT, WITHOUT REGARD TO CONFLICT OF LAWS PRINCIPLES.\"}},{\"id\":\"P3SN2EC1bi\",\"type\":\"paragraph\",\"data\":{\"text\":\"VENUE OF JURISDICTION\"}},{\"id\":\"Qw4EyGKtGL\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE EXCLUSIVE COMPETENCE TO DECIDE ON ANY CONTROVERSY RESULTING FROM OR CONNECTED TO THESE TERMS LIES WITH THE COURTS OF THE PLACE WHERE THE OWNER IS BASED, AS DISPLAYED IN THE RELEVANT SECTION OF THIS DOCUMENT.\"}},{\"id\":\"UyogGrR-JJ\",\"type\":\"paragraph\",\"data\":{\"text\":\"SURVIVING PROVISIONS\"}},{\"id\":\"Uw66j-sFNS\",\"type\":\"paragraph\",\"data\":{\"text\":\"THIS AGREEMENT SHALL CONTINUE IN EFFECT UNTIL IT IS TERMINATED BY EITHER THIS WEBSITE OR THE USER. UPON TERMINATION, THE PROVISIONS CONTAINED IN THESE TERMS THAT BY THEIR CONTEXT ARE INTENDED TO SURVIVE TERMINATION OR EXPIRATION WILL SURVIVE, INCLUDING BUT NOT LIMITED TO THE FOLLOWING:\"}},{\"id\":\"AlvKEuVvja\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[\"THE USER’S GRANT OF LICENSES UNDER THESE TERMS SHALL SURVIVE INDEFINITELY;\",\"THE USER’S INDEMNIFICATION OBLIGATIONS SHALL SURVIVE FOR A PERIOD OF FIVE YEARS FROM THE DATE OF TERMINATION;\",\"THE DISCLAIMER OF WARRANTIES AND REPRESENTATIONS, AND THE STIPULATIONS UNDER THE SECTION CONTAINING INDEMNITY AND LIMITATION OF LIABILITY PROVISIONS, SHALL SURVIVE INDEFINITELY.\"]}},{\"id\":\"35slpXy1wS\",\"type\":\"paragraph\",\"data\":{\"text\":\"DISPUTE RESOLUTION\"}},{\"id\":\"YxKKfH2XWb\",\"type\":\"paragraph\",\"data\":{\"text\":\"AMICABLE DISPUTE RESOLUTION\"}},{\"id\":\"RYRA4atOer\",\"type\":\"paragraph\",\"data\":{\"text\":\"USERS MAY BRING ANY DISPUTES TO THE OWNER WHO WILL TRY TO RESOLVE THEM AMICABLY.\"}},{\"id\":\"IU1cM7d_zk\",\"type\":\"paragraph\",\"data\":{\"text\":\"WHILE USERS\' RIGHT TO TAKE LEGAL ACTION SHALL ALWAYS REMAIN UNAFFECTED, IN THE EVENT OF ANY CONTROVERSY REGARDING THE USE OF THIS WEBSITE OR THE SERVICE, USERS ARE KINDLY ASKED TO CONTACT THE OWNER AT THE CONTACT DETAILS PROVIDED IN THIS DOCUMENT.\"}},{\"id\":\"yKETGeIs5U\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE USER MAY SUBMIT THE COMPLAINT INCLUDING A BRIEF DESCRIPTION AND IF APPLICABLE, THE DETAILS OF THE RELATED ORDER, PURCHASE, OR ACCOUNT, TO THE OWNER’S EMAIL ADDRESS SPECIFIED IN THIS DOCUMENT.\"}},{\"id\":\"3FFFoquKSd\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE OWNER WILL PROCESS THE COMPLAINT WITHOUT UNDUE DELAY AND WITHIN 14 DAYS OF RECEIVING IT.\"}},{\"id\":\"zDiHf6qSWP\",\"type\":\"paragraph\",\"data\":{\"text\":\"APPOINTMENT RISKS; COVID-19\"}},{\"id\":\"PAHOjURh1N\",\"type\":\"paragraph\",\"data\":{\"text\":\"YOU AGREE THAT APPOINTMENTS MAY CARRY INHERENT RISK, AND BY REQUESTING THE SERVICES, YOU CHOOSE TO ASSUME THOSE RISKS VOLUNTARILY. FOR EXAMPLE, THE SERVICES MAY CARRY RISK OF ILLNESS, BODILY INJURY, DISABILITY OR DEATH, AND YOU FREELY AND WILLFULLY ASSUME THOSE RISKS BY REQUESTING SERVICES. YOU ASSUME FULL RESPONSIBILITY FOR THE CHOICES YOU MAKE BEFORE, DURING, AND AFTER ANY APPOINTMENT. BY SHOWING UP TO AN APPOINTMENT, YOU REPRESENT AND WARRANT THAT YOU:\"}},{\"id\":\"Xqs_Z3dol8\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[\"DO NOT HAVE A COUGH, FEVER, OR OTHER SYMPTOMS OF COVID-19;&nbsp;\",\"HAVE NOT TESTED POSITIVE FOR COVID-19 OR SARS-COV-2 IN THE LAST TWENTY (20) DAYS; AND&nbsp;\",\"HAVE NOT BEEN EXPOSED OR COME INTO CONTACT IN THE LAST TWENTY (20) DAYS WITH ANYONE WHO HAS TESTED POSITIVE FOR COVID-19 OR SARS-COV-2.\"]}},{\"id\":\"3hfxjEVwo1\",\"type\":\"paragraph\",\"data\":{\"text\":\"FEEDBACK\"}},{\"id\":\"HcVZfG5oT4\",\"type\":\"paragraph\",\"data\":{\"text\":\"THE OWNER IS PLEASED TO HEAR FROM ITS USERS, HOWEVER YOU AGREE THAT WE WILL BE FREE TO USE, FOR ANY PURPOSE WHATSOEVER, ANY FEEDBACK, SUGGESTIONS, IDEAS OR CREATIVE MATERIALS YOU DISCLOSE OR OFFER TO US (“FEEDBACK”), INCLUDING VIA E-MAILS OR TELEPHONE CALLS. ANY SUCH FEEDBACK IS PROVIDED ON A NON-CONFIDENTIAL BASIS WITH NO OBLIGATION ON OUR PART TO KEEP SUCH INFORMATION SECRET. BY UPLOADING OR OTHERWISE PROVIDING ANY FEEDBACK, YOU HEREBY GRANT THE OWNER, THE UNLIMITED, PERPETUAL RIGHT TO USE, REUSE, REDISTRIBUTE, MODIFY AND CREATE DERIVATIVE WORKS FROM SUCH FEEDBACK FOR ANY PURPOSE AND IN ANY MEDIA WITHOUT COMPENSATION, INCLUDING BUT NOT LIMITED TO PUBLISHING, OR DEVELOPING, MANUFACTURING, AND MARKETING PRODUCTS OR SERVICES USING SUCH FEEDBACK, AND YOU WARRANT THAT ALL “MORAL RIGHTS” IN FEEDBACK HAVE BEEN WAIVED.&nbsp;\"}}],\"version\":\"2.22.2\"}','2021-06-11 09:45:11','2021-11-26 00:12:41',NULL),(2,'Privacy policy','privacy-policy','/privacy','Privacy policy','Privacy policy','{\"time\":1637886848787,\"blocks\":[{\"id\":\"ynJlk4CJHj\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Modern Citi Group</b> (“we,” “our,” or “us”) is committed to protecting your privacy. This Privacy Policy explains how your personal information is collected, used, and disclosed by Modern Citi Group.\"}},{\"id\":\"Fw1XwEj7Kr\",\"type\":\"paragraph\",\"data\":{\"text\":\"This Privacy Policy applies to our website, and its associated subdomains (collectively, our “Service”) alongside our application, Modern Citi Group. By accessing or using our Service, you signify that you have read, understood, and agree to our collection, storage, use, and disclosure of your personal information as described in this <b>Privacy Policy</b> and our <b>Terms of Use</b>.\"}},{\"id\":\"4t61Rn99uK\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"ZcuOmEqdSO\",\"type\":\"header\",\"data\":{\"text\":\"Definitions and key terms\",\"level\":2}},{\"id\":\"XeI7zWxxeV\",\"type\":\"paragraph\",\"data\":{\"text\":\"To help explain things as clearly as possible in this Privacy Policy, every time any of these terms are referenced, are strictly defined as:\"}},{\"id\":\"_X6soFTfDX\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Cookie</b>: small amount of data generated by a website and saved by your web browser. It is used to identify your browser, provide analytics, remember information about you such as your language preference or login information.\"}},{\"id\":\"rKJzNqq8o_\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Company</b>: when this policy mentions “Company,” “we,” “us,” or “our,” it refers to Modern Citi Group, 1572 Dahill Road, Brooklyn, NY 11204, US that is responsible for your information under this Privacy Policy.\"}},{\"id\":\"93vt6QUCb4\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Country</b>: where Modern Citi Group or the owners/founders of Modern Citi Group are based, in this case is the United States\"}},{\"id\":\"kylH8J2WAX\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Customer</b>: refers to the company, organization or person that signs up to use the Modern Citi Group Service to manage the relationships with your consumers or service users.\"}},{\"id\":\"Erud8qKMhc\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Device</b>: any internet connected device such as a phone, tablet, computer or any other device that can be used to visit Modern Citi Group and use the services.\"}},{\"id\":\"3jP_ct3ZTC\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>IP address</b>: Every device connected to the Internet is assigned a number known as an Internet protocol (IP) address. These numbers are usually assigned in geographic blocks. An IP address can often be used to identify the location from which a device is connecting to the Internet.\"}},{\"id\":\"3preKUfheh\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Personnel</b>: refers to those individuals who are employed by Modern Citi Group or are under contract to perform a service on behalf of one of the parties.\"}},{\"id\":\"10eS1aKrUZ\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Personal Data</b>: any information that directly, indirectly, or in connection with other information — including a personal identification number — allows for the identification or identifiability of a natural person.\"}},{\"id\":\"UMlCDPSzU3\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Service</b>: refers to the service provided by Modern Citi Group as described in the relative terms (if available) and on this platform.\"}},{\"id\":\"X5IgeWPLoR\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Third-party service</b>: refers to advertisers, contest sponsors, promotional and marketing partners, and others who provide our content or whose products or services we think may interest you.\"}},{\"id\":\"OXZo2vF-F4\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Website</b>: Modern Citi Group’s site, which can be accessed via this URL: <a href=\\\"https://modernciti.group.com\\\" target=\\\"_self\\\">https://moderncitigroup.com</a>\"}},{\"id\":\"jWyFhh5Jz0\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>You</b>: a person or entity that is registered with Modern Citi Group to use the Services.\"}},{\"id\":\"wf8q0unheW\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"jxoXGC8UHB\",\"type\":\"header\",\"data\":{\"text\":\"What Information Do We Collect?\",\"level\":2}},{\"id\":\"wCScGj9YYE\",\"type\":\"paragraph\",\"data\":{\"text\":\"We collect information from you when you visit our website, register on our site, place an order, subscribe to our newsletter, respond to a survey or fill out a form.\"}},{\"id\":\"Xmd41eZSG2\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[\"Name / Username\",\"Phone Numbers<br>\",\"Email Addresses<br>\",\"Mailing Addresses<br>\",\"Billing Addresses<br>\",\"Age<br>\"]}},{\"id\":\"N9K9353Yrg\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"We-j7Q-gRG\",\"type\":\"header\",\"data\":{\"text\":\"When does Modern Citi Group use end user information from third parties?\",\"level\":2}},{\"id\":\"px5AvbQbkw\",\"type\":\"paragraph\",\"data\":{\"text\":\"Modern Citi Group will collect End User Data necessary to provide the Modern Citi Group services to our customers. End users may voluntarily provide us with information they have made available on social media websites. If you provide us with any such information, we may collect publicly available information from the social media websites you have indicated. You can control how much of your information social media websites make public by visiting these websites and changing your privacy settings.\"}},{\"id\":\"JzqJvMXtFa\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"i9xrH2ZJV4\",\"type\":\"header\",\"data\":{\"text\":\"When does Modern Citi Group use customer information from third parties?\",\"level\":2}},{\"id\":\"apzeb7fEXA\",\"type\":\"paragraph\",\"data\":{\"text\":\"We receive some information from the third parties when you contact us. For example, when you submit your email address to us to show interest in becoming a Modern Citi Group customer, we receive information from a third party that provides automated fraud detection services to Modern Citi Group. We also occasionally collect information that is made publicly available on social media websites. You can control how much of your information social media websites make public by visiting these websites and changing your privacy settings.\"}},{\"id\":\"o5XkBc-9EI\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"k989vLx4P4\",\"type\":\"header\",\"data\":{\"text\":\"Do we share the information we collect with third parties?\",\"level\":2}},{\"id\":\"y--SVWzHRS\",\"type\":\"paragraph\",\"data\":{\"text\":\"We may share the information that we collect, both personal and non-personal, with third parties such as advertisers, contest sponsors, promotional and marketing partners, and others who provide our content or whose products or services we think may interest you. We may also share it with our current and future affiliated companies and business partners, and if we are involved in a merger, asset sale or other business reorganization, we may also share or transfer your personal and non-personal information to our successors-in-interest.\"}},{\"id\":\"dcKByFVwyu\",\"type\":\"paragraph\",\"data\":{\"text\":\"We may engage trusted third party service providers to perform functions and provide services to us, such as hosting and maintaining our servers and the website, database storage and management, e-mail management, storage marketing, credit card processing, customer service and fulfilling orders for products and services you may purchase through the website. We will likely share your personal information, and possibly some non-personal information, with these third parties to enable them to perform these services for us and for you.\"}},{\"id\":\"63pVkxLwjF\",\"type\":\"paragraph\",\"data\":{\"text\":\"We may share portions of our log file data, including IP addresses, for analytics purposes with third parties such as web analytics partners, application developers, and ad networks. If your IP address is shared, it may be used to estimate general location and other technographics such as connection speed, whether you have visited the website in a shared location, and type of the device used to visit the website. They may aggregate information about our advertising and what you see on the website and then provide auditing, research and reporting for us and our advertisers.\"}},{\"id\":\"J_w2easQMV\",\"type\":\"paragraph\",\"data\":{\"text\":\"We may also disclose personal and non-personal information about you to government or law enforcement officials or private parties as we, in our sole discretion, believe necessary or appropriate in order to respond to claims, legal process (including subpoenas), to protect our rights and interests or those of a third party, the safety of the public or any person, to prevent or stop any illegal, unethical, or legally actionable activity, or to otherwise comply with applicable court orders, laws, rules and regulations.\"}},{\"id\":\"PQ6iVtPkAQ\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"ZlK8ooHSEp\",\"type\":\"header\",\"data\":{\"text\":\"Where and when is information collected from customers and end users?\",\"level\":2}},{\"id\":\"RCtjXUHQo5\",\"type\":\"paragraph\",\"data\":{\"text\":\"Modern Citi Group will collect personal information that you submit to us. We may also receive personal information about you from third parties as described above.\"}},{\"id\":\"NN6Ta1Fuaz\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"DAozauqKmy\",\"type\":\"header\",\"data\":{\"text\":\"How Do We Use The Information We Collect?\",\"level\":2}},{\"id\":\"oasqN69YI7\",\"type\":\"paragraph\",\"data\":{\"text\":\"Any of the information we collect from you may be used in one of the following ways:\"}},{\"id\":\"ZQyGyacqxY\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[\"To personalize your experience (your information helps us to better respond to your individual needs)\",\"&nbsp;To improve our website (we continually strive to improve our website offerings based on the information and feedback we receive from you)<br>\",\"To improve customer service (your information helps us to more effectively respond to your customer service requests and support needs)<br>\",\"To process transactions<br>\",\"To administer a contest, promotion, survey or other site feature<br>\",\"To send periodic emails<br>\"]}},{\"id\":\"eKJpUmN6bX\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"dvv3Q_mfq1\",\"type\":\"header\",\"data\":{\"text\":\"How Do We Use Your Email Address?\",\"level\":2}},{\"id\":\"ZwAMBPCTA7\",\"type\":\"paragraph\",\"data\":{\"text\":\"By submitting your email address on this website, you agree to receive emails from us. You can cancel your participation in any of these email lists at any time by clicking on the opt-out link or other unsubscribe option that is included in the respective email. We only send emails to people who have authorized us to contact them, either directly, or through a third party. We do not send unsolicited commercial emails, because we hate spam as much as you do. By submitting your email address, you also agree to allow us to use your email address for customer audience targeting on sites like Facebook, where we display custom advertising to specific people who have opted-in to receive communications from us. Email addresses submitted only through the order processing page will be used for the sole purpose of sending you information and updates pertaining to your order. If, however, you have provided the same email to us through another method, we may use it for any of the purposes stated in this Policy. Note: If at any time you would like to unsubscribe from receiving future emails, we include detailed unsubscribe instructions at the bottom of each email.\"}},{\"id\":\"1FPwqoxIPm\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"mcG0yLmRYJ\",\"type\":\"header\",\"data\":{\"text\":\"How Long Do We Keep Your Information?\",\"level\":2}},{\"id\":\"39NxQMg1On\",\"type\":\"paragraph\",\"data\":{\"text\":\"We keep your information only so long as we need it to provide Modern Citi Group to you and fulfill the purposes described in this policy. This is also the case for anyone that we share your information with and who carries out services on our behalf. When we no longer need to use your information and there is no need for us to keep it to comply with our legal or regulatory obligations, we’ll either remove it from our systems or depersonalize it so that we can\'t identify you.\"}},{\"id\":\"bOq3NTjUhC\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"n0qb93YPlv\",\"type\":\"header\",\"data\":{\"text\":\"How Do We Protect Your Information?\",\"level\":2}},{\"id\":\"kJfOgLQhc3\",\"type\":\"paragraph\",\"data\":{\"text\":\"We implement a variety of security measures to maintain the safety of your personal information when you place an order or enter, submit, or access your personal information. We offer the use of a secure server. All supplied sensitive/credit information is transmitted via Secure Socket Layer (SSL) technology and then encrypted into our Payment gateway providers database only to be accessible by those authorized with special access rights to such systems, and are required to keep the information confidential. After a transaction, your private information (credit cards, social security numbers, financials, etc.) is never kept on file. We cannot, however, ensure or warrant the absolute security of any information you transmit to Modern Citi Group or guarantee that your information on the Service may not be accessed, disclosed, altered, or destroyed by a breach of any of our physical, technical, or managerial safeguards.\"}},{\"id\":\"ICDR3d7-v4\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"AtARwCnAZD\",\"type\":\"header\",\"data\":{\"text\":\"Could my information be transferred to other countries?\",\"level\":2}},{\"id\":\"ztspIschTT\",\"type\":\"paragraph\",\"data\":{\"text\":\"Modern Citi Group is incorporated in the United States. Information collected via our website, through direct interactions with you, or from use of our help services may be transferred from time to time to our offices or personnel, or to third parties, located throughout the world, and may be viewed and hosted anywhere in the world, including countries that may not have laws of general applicability regulating the use and transfer of such data. To the fullest extent allowed by applicable law, by using any of the above, you voluntarily consent to the trans-border transfer and hosting of such information.\"}},{\"id\":\"p-Vz-Go7kB\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"DAP48Fz8S3\",\"type\":\"header\",\"data\":{\"text\":\"Is the information collected through the Modern Citi Group Service secure?\",\"level\":2}},{\"id\":\"egZdO4By6S\",\"type\":\"paragraph\",\"data\":{\"text\":\"We take precautions to protect the security of your information. We have physical, electronic, and managerial procedures to help safeguard, prevent unauthorized access, maintain data security, and correctly use your information. However, neither people nor security systems are foolproof, including encryption systems. In addition, people can commit intentional crimes, make mistakes or fail to follow policies. Therefore, while we use reasonable efforts to protect your personal information, we cannot guarantee its absolute security. If applicable law imposes any non-disclaimable duty to protect your personal information, you agree that intentional misconduct will be the standards used to measure our compliance with that duty.\"}},{\"id\":\"bwS1nVgd4T\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"X_gukt4QOw\",\"type\":\"header\",\"data\":{\"text\":\"Can I update or correct my information?\",\"level\":2}},{\"id\":\"C2ROeMT50i\",\"type\":\"paragraph\",\"data\":{\"text\":\"The rights you have to request updates or corrections to the information Modern Citi Group collects depend on your relationship with Modern Citi Group. Personnel may update or correct their information as detailed in our internal company employment policies.\"}},{\"id\":\"QLzTH_zXEO\",\"type\":\"paragraph\",\"data\":{\"text\":\"Customers have the right to request the restriction of certain uses and disclosures of personally identifiable information as follows. You can contact us in order to (1) update or correct your personally identifiable information, (2) change your preferences with respect to communications and other information you receive from us, or (3) delete the personally identifiable information maintained about you on our systems (subject to the following paragraph), by cancelling your account. Such updates, corrections, changes and deletions will have no effect on other information that we maintain, or information that we have provided to third parties in accordance with this Privacy Policy prior to such update, correction, change or deletion. To protect your privacy and security, we may take reasonable steps (such as requesting a unique password) to verify your identity before granting you profile access or making corrections. You are responsible for maintaining the secrecy of your unique password and account information at all times.\"}},{\"id\":\"1tESIdlN_C\",\"type\":\"paragraph\",\"data\":{\"text\":\"You should be aware that it is not technologically possible to remove each and every record of the information you have provided to us from our system. The need to back up our systems to protect information from inadvertent loss means that a copy of your information may exist in a non-erasable form that will be difficult or impossible for us to locate. Promptly after receiving your request, all personal information stored in databases we actively use, and other readily searchable media will be updated, corrected, changed or deleted, as appropriate, as soon as and to the extent reasonably and technically practicable.\"}},{\"id\":\"b6PIX1bITs\",\"type\":\"paragraph\",\"data\":{\"text\":\"If you are an end user and wish to update, delete, or receive any information we have about you, you may do so by contacting the organization of which you are a customer.\"}},{\"id\":\"HMe-yEtzUJ\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"Gg80apmeoo\",\"type\":\"header\",\"data\":{\"text\":\"Personnel\",\"level\":2}},{\"id\":\"Ao5i_whZaz\",\"type\":\"paragraph\",\"data\":{\"text\":\"If you are a Modern Citi Group worker or applicant, we collect information you voluntarily provide to us. We use the information collected for Human Resources purposes in order to administer benefits to workers and screen applicants.\"}},{\"id\":\"uYtRIPcyv4\",\"type\":\"paragraph\",\"data\":{\"text\":\"You may contact us in order to (1) update or correct your information, (2) change your preferences with respect to communications and other information you receive from us, or (3) receive a record of the information we have relating to you. Such updates, corrections, changes and deletions will have no effect on other information that we maintain, or information that we have provided to third parties in accordance with this Privacy Policy prior to such update, correction, change or deletion.\"}},{\"id\":\"6imPeJmtdz\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"oxyftimb1C\",\"type\":\"header\",\"data\":{\"text\":\"Sale of Business\",\"level\":2}},{\"id\":\"g40iAFLff8\",\"type\":\"paragraph\",\"data\":{\"text\":\"We reserve the right to transfer information to a third party in the event of a sale, merger or other transfer of all or substantially all of the assets of Modern Citi Group or any of its Corporate Affiliates (as defined herein), or that portion of Modern Citi Group or any of its Corporate Affiliates to which the Service relates, or in the event that we discontinue our business or file a petition or have filed against us a petition in bankruptcy, reorganization or similar proceeding, provided that the third party agrees to adhere to the terms of this Privacy Policy.\"}},{\"id\":\"XZB-knUy7h\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"7c6iLOAAqh\",\"type\":\"header\",\"data\":{\"text\":\"Affiliates\",\"level\":2}},{\"id\":\"mg8HYpyDIW\",\"type\":\"paragraph\",\"data\":{\"text\":\"We may disclose information (including personal information) about you to our Corporate Affiliates. For purposes of this Privacy Policy, \\\"Corporate Affiliate\\\" means any person or entity which directly or indirectly controls, is controlled by or is under common control with Modern Citi Group, whether by ownership or otherwise. Any information relating to you that we provide to our Corporate Affiliates will be treated by those Corporate Affiliates in accordance with the terms of this Privacy Policy.\"}},{\"id\":\"VGFqWQyqOm\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"xwOql_XdND\",\"type\":\"header\",\"data\":{\"text\":\"Governing Law\",\"level\":2}},{\"id\":\"JfQM5QMs-_\",\"type\":\"paragraph\",\"data\":{\"text\":\"This Privacy Policy is governed by the laws of The United States without regard to its conflict of laws provision. You consent to the exclusive jurisdiction of the courts in connection with any action or dispute arising between the parties under or in connection with this Privacy Policy except for those individuals who may have rights to make claims under Privacy Shield, or the Swiss-US framework.\"}},{\"id\":\"VmwksqXtJc\",\"type\":\"paragraph\",\"data\":{\"text\":\"The laws of The United States, excluding its conflicts of law rules, shall govern this Agreement and your use of the website. Your use of the website may also be subject to other local, state, national, or international laws.\"}},{\"id\":\"GOzY5RUMWy\",\"type\":\"paragraph\",\"data\":{\"text\":\"By using Modern Citi Group or contacting us directly, you signify your acceptance of this Privacy Policy. If you do not agree to this Privacy Policy, you should not engage with our website, or use our services. Continued use of the website, direct engagement with us, or following the posting of changes to this Privacy Policy that do not significantly affect the use or disclosure of your personal information will mean that you accept those changes.\"}},{\"id\":\"Y1-6_mh7ge\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"nb5X801uy8\",\"type\":\"header\",\"data\":{\"text\":\"Your Consent\",\"level\":2}},{\"id\":\"Hbcdk_1ol5\",\"type\":\"paragraph\",\"data\":{\"text\":\"We\'ve updated our Privacy Policy to provide you with complete transparency into what is being set when you visit our site and how it\'s being used. By using our Modern Citi Group, registering an account, or making a purchase, you hereby consent to our Privacy Policy and agree to its terms.\"}},{\"id\":\"qLDs92tHRm\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"5q0JzshFds\",\"type\":\"header\",\"data\":{\"text\":\"Links to Other Websites\",\"level\":2}},{\"id\":\"_kHzRiYG64\",\"type\":\"paragraph\",\"data\":{\"text\":\"This Privacy Policy applies only to the Services. The Services may contain links to other websites not operated or controlled by Modern Citi Group. We are not responsible for the content, accuracy or opinions expressed in such websites, and such websites are not investigated, monitored or checked for accuracy or completeness by us. Please remember that when you use a link to go from the Services to another website, our Privacy Policy is no longer in effect. Your browsing and interaction on any other website, including those that have a link on our platform, is subject to that website’s own rules and policies. Such third parties may use their own cookies or other methods to collect information about you.\"}},{\"id\":\"IPn-qb4L2B\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"Clqq8152-X\",\"type\":\"header\",\"data\":{\"text\":\"Cookies\",\"level\":2}},{\"id\":\"ZHa7dHRfH6\",\"type\":\"paragraph\",\"data\":{\"text\":\"Modern Citi Group uses \\\"Cookies\\\" to identify the areas of our website that you have visited. A Cookie is a small piece of data stored on your computer or mobile device by your web browser. We use Cookies to enhance the performance and functionality of our website but are non-essential to their use. However, without these cookies, certain functionality like videos may become unavailable or you would be required to enter your login details every time you visit the website as we would not be able to remember that you had logged in previously. Most web browsers can be set to disable the use of Cookies. However, if you disable Cookies, you may not be able to access functionality on our website correctly or at all. We never place Personally Identifiable Information in Cookies.\"}},{\"id\":\"P0bBeCosQa\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"ycfRUC_vDb\",\"type\":\"header\",\"data\":{\"text\":\"Blocking and disabling cookies and similar technologies\",\"level\":2}},{\"id\":\"-NdK0HWgrJ\",\"type\":\"paragraph\",\"data\":{\"text\":\"Wherever you\'re located you may also set your browser to block cookies and similar technologies, but this action may block our essential cookies and prevent our website from functioning properly, and you may not be able to fully utilize all of its features and services. You should also be aware that you may also lose some saved information (e.g. saved login details, site preferences) if you block cookies on your browser. Different browsers make different controls available to you. Disabling a cookie or category of cookie does not delete the cookie from your browser, you will need to do this yourself from within your browser, you should visit your browser\'s help menu for more information.\"}},{\"id\":\"uOot2XBJZK\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"mh5Gr7iKge\",\"type\":\"header\",\"data\":{\"text\":\"Changes To Our Privacy Policy\",\"level\":2}},{\"id\":\"Igp5tsajLo\",\"type\":\"paragraph\",\"data\":{\"text\":\"We may change our Service and policies, and we may need to make changes to this Privacy Policy so that they accurately reflect our Service and policies. Unless otherwise required by law, we will notify you (for example, through our Service) before we make changes to this Privacy Policy and give you an opportunity to review them before they go into effect. Then, if you continue to use the Service, you will be bound by the updated Privacy Policy. If you do not want to agree to this or any updated Privacy Policy, you can delete your account.\"}},{\"id\":\"CJNoQwBPRy\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"2qtZhPas45\",\"type\":\"header\",\"data\":{\"text\":\"Third-Party Services\",\"level\":2}},{\"id\":\"qhrYsInnzM\",\"type\":\"paragraph\",\"data\":{\"text\":\"We may display, include or make available third-party content (including data, information, applications and other products services) or provide links to third-party websites or services (\\\"Third- Party Services\\\").\"}},{\"id\":\"4eX5yOqF2e\",\"type\":\"paragraph\",\"data\":{\"text\":\"You acknowledge and agree that Modern Citi Group shall not be responsible for any Third-Party Services, including their accuracy, completeness, timeliness, validity, copyright compliance, legality, decency, quality or any other aspect thereof. Modern Citi Group does not assume and shall not have any liability or responsibility to you or any other person or entity for any Third-Party Services.\"}},{\"id\":\"6MoBQbvWy7\",\"type\":\"paragraph\",\"data\":{\"text\":\"Third-Party Services and links thereto are provided solely as a convenience to you and you access and use them entirely at your own risk and subject to such third parties\' terms and conditions.\"}},{\"id\":\"fj-RcJ25BF\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"zQK7lFpR5e\",\"type\":\"header\",\"data\":{\"text\":\"Tracking Technologies\",\"level\":2}},{\"id\":\"u7yQ75gQHh\",\"type\":\"header\",\"data\":{\"text\":\"Cookies \",\"level\":3}},{\"id\":\"nXHzBFHb9i\",\"type\":\"paragraph\",\"data\":{\"text\":\"We use Cookies to enhance the performance and functionality of our but are non-essential to their use. However, without these cookies, certain functionality like videos may become unavailable or you would be required to enter your login details every time you visit the as we would not be able to remember that you had logged in previously.\"}},{\"id\":\"pWxiZEXOU7\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;\"}},{\"id\":\"d7t_JYCE3k\",\"type\":\"header\",\"data\":{\"text\":\"Contact Us\",\"level\":2}},{\"id\":\"HudHjY_8_S\",\"type\":\"paragraph\",\"data\":{\"text\":\"Don\'t hesitate to contact us if you have any questions.\"}},{\"id\":\"B34tB2Dd0k\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[\"Via Email: contact@moderncitigroup.com\",\"Via Phone Number: +1 844 624 00 44<br>\",\"Via this Link: https://moderncitigroup.com<br>\"]}}],\"version\":\"2.22.2\"}','2021-06-11 10:41:31','2021-11-26 00:34:09',NULL),(3,'TEST 1','test','https://crm.modernciti.group/control/static-pages/create','TEST','TEST 222','{\"time\":1630568047021,\"blocks\":[{\"id\":\"5GN5wu5HxW\",\"type\":\"paragraph\",\"data\":{\"text\":\"TEST 222\"}}],\"version\":\"2.22.0\"}','2021-09-02 07:33:39','2021-09-02 07:34:23','2021-09-02 07:34:23');
