DROP TABLE IF EXISTS `subcontractors`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `subcontractors` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `company_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Название компании',
  `primary_contact_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Имя главной персоны',
  `phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Телефон',
  `type_id` bigint(20) unsigned DEFAULT NULL,
  `vendor_source_id` bigint(20) unsigned DEFAULT NULL,
  `parent_id` bigint(20) unsigned DEFAULT NULL,
  `status_id` bigint(20) unsigned DEFAULT NULL,
  `website` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Сайт',
  `has_project` tinyint(1) DEFAULT NULL,
  `workers_compensation` tinyint(1) DEFAULT NULL,
  `licensed` tinyint(1) DEFAULT NULL,
  `general_liability` tinyint(1) DEFAULT NULL,
  `crew_size` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `languages` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `drivers_license` tinyint(1) DEFAULT NULL,
  `has_tools` tinyint(1) DEFAULT NULL,
  `has_vehicle` tinyint(1) DEFAULT NULL,
  `years_of_experience` int(11) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `subcontractors_user_id_foreign` (`user_id`),
  KEY `subcontractors_type_id_foreign` (`type_id`),
  KEY `subcontractors_vendor_source_id_foreign` (`vendor_source_id`),
  KEY `subcontractors_parent_id_foreign` (`parent_id`),
  KEY `subcontractors_status_id_foreign` (`status_id`),
  CONSTRAINT `subcontractors_parent_id_foreign` FOREIGN KEY (`parent_id`) REFERENCES `subcontractors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `subcontractors_status_id_foreign` FOREIGN KEY (`status_id`) REFERENCES `statuses` (`id`) ON DELETE CASCADE,
