--
-- Table structure for table `works`
--

DROP TABLE IF EXISTS `works`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `works` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `price` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `size` int(11) DEFAULT NULL,
  `kuula_link` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `short_description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `build_text` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `design_text` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plan_text` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `designer` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `work_started_at` timestamp NULL DEFAULT NULL,
  `work_finished_at` timestamp NULL DEFAULT NULL,
  `state_id` bigint(20) unsigned DEFAULT NULL,
  `review_id` bigint(20) unsigned DEFAULT NULL,
  `price_prefix` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price_to` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `works_state_id_foreign` (`state_id`),
  KEY `works_review_id_foreign` (`review_id`),
  CONSTRAINT `works_review_id_foreign` FOREIGN KEY (`review_id`) REFERENCES `reviews` (`id`) ON DELETE CASCADE,
  CONSTRAINT `works_state_id_foreign` FOREIGN KEY (`state_id`) REFERENCES `states` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

